# Compare the tables and number macros regenerated by main.jl (working tree) with the
# committed ones (git HEAD): the web site must show what the committed paper shows.
#
#   julia applications/jtcam-tex/web/check_results.jl [--ref=<git rev>]
#
# Numbers are compared with a relative tolerance RTOL; the macros of HOST_DEPENDENT are
# values known to change with the host (floating-point noise at the level of the solver
# tolerance) and get their own rule. Exits with status 1 on a difference.

const ROOT = dirname(@__DIR__)
const RTOL = 1e-5  # tables print about 6 significant digits; b is printed with more (review finding 10)

# macro => check(committed, regenerated) on the numbers of its line
const HOST_DEPENDENT = Dict(
    # \SigmaGap = 10^{e}: σ-invariance gap of the cycles, at the integration noise (1e-9 locally, 1e-8 on the runners)
    "SigmaGap" => (a, b) -> all(abs.(a .- b) .<= 1),
)

const NUM = r"[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?"

numbers(s) = [parse(Float64, m.match) for m in eachmatch(NUM, s)]
skeleton(s) = replace(s, NUM => "#")
macro_of(s) = (m = match(r"\\newcommand\{\\([A-Za-z]+)\}", s); m === nothing ? nothing : m.captures[1])

function compare(file, ref)
    old = readlines(IOBuffer(read(`git -C $ROOT show $ref:./$file`, String)))
    new = readlines(joinpath(ROOT, file))
    errs = String[]
    length(old) == length(new) || return ["$file: $(length(old)) lines committed, $(length(new)) regenerated"]
    for (i, (a, b)) in enumerate(zip(old, new))
        a == b && continue
        if skeleton(a) != skeleton(b)
            push!(errs, "$file:$i: text differs\n  committed:   $a\n  regenerated: $b")
            continue
        end
        x, y = numbers(a), numbers(b)
        m = macro_of(a)
        ok = if m !== nothing && haskey(HOST_DEPENDENT, m)
            HOST_DEPENDENT[m](x, y)
        elseif occursin("residual", a)
            # solver residuals: floating-point noise below the tolerance, compare orders of magnitude
            m = "residual"
            all(abs.(round.(log10.(abs.(x) .+ 1e-300)) .- round.(log10.(abs.(y) .+ 1e-300))) .<= 1)
        else
            all(isapprox.(x, y; rtol=RTOL))
        end
        ok ? println("  $file:$i: within tolerance ($(something(m, "numbers")))") :
             push!(errs, "$file:$i: numbers differ\n  committed:   $a\n  regenerated: $b")
    end
    return errs
end

function main(args=ARGS)
    a = findfirst(startswith("--ref="), args)
    ref = a === nothing ? "HEAD" : args[a][7:end]
    files = sort(filter(f -> endswith(f, ".tex"), readdir(joinpath(ROOT, "tables"))))
    errs = String[]
    for f in files
        append!(errs, compare("tables/$f", ref))
    end
    if isempty(errs)
        println("check_results: the $(length(files)) regenerated tables agree with $ref")
    else
        foreach(println, errs)
        println("check_results: $(length(errs)) difference(s) with $ref")
        exit(1)
    end
end

main()
